OPTS3 = ["משפט פשוט", "משפט מחובר", "משפט מורכב", "צירוף, לא משפט"]
def TYPE(q, ans, sent, e, expl):
    return Q(SNT, q, [OPTS3[ans]] + [o for i, o in enumerate(OPTS3) if i != ans], expl, S(sent, e=e))

